def test_exhaustive_01(run, x):
    from itertools import permutations
    z = x.split()
    h, w = map(int, z[:2])
    g = z[2:]
    ok = False
    for rp in permutations(range(h)):
        for cp in permutations(range(w)):
            if all(g[rp[i]][cp[j]] == g[rp[h-1-i]][cp[w-1-j]] for i in range(h) for j in range(w)):
                ok = True
                break
        if ok:
            break
    assert run(x).strip() == ('YES' if ok else 'NO')


