def test_integer_range(run, x):
    p = list(map(int, x.split()))
    n = p[0]
    out = run(x).strip()
    assert out and out.lstrip('-').isdigit()
    assert 0 <= int(out) <= n


def test_exact_window(run, x):
    p = list(map(int, x.split())); n, I = p[:2]; a = p[2:]
    v = sorted(set(a)); b = (8 * I) // n
    cap = len(v) if b >= len(v).bit_length() else (1 << b)
    best = 0
    for i in range(len(v)):
        kept = 0
        for j in range(i, min(len(v), i + cap)):
            kept += a.count(v[j])
            best = max(best, kept)
    assert run(x).strip() == str(n - best)


def test_exact_literal_clipping(run, x):
    p = list(map(int, x.split())); n, I = p[:2]; a = p[2:]
    v = sorted(set(a)); b = (8 * I) // n
    cap = len(v) if b >= len(v).bit_length() else (1 << b)
    ans = n
    for l in v:
        for r in v:
            if l <= r:
                z = [l if q < l else r if q > r else q for q in a]
                if len(set(z)) <= cap:
                    ans = min(ans, sum(q != w for q, w in zip(a, z)))
    assert run(x).strip() == str(ans)


def test_exact_frequency_blocks(run, x):
    p = list(map(int, x.split())); n, I = p[:2]; a = p[2:]
    freq = {}
    for q in a: freq[q] = freq.get(q, 0) + 1
    v = sorted(freq); b = (8 * I) // n
    cap = len(v) if b >= len(v).bit_length() else 1 << b
    best = max(sum(freq[v[t]] for t in range(s, min(len(v), s + cap))) for s in range(len(v)))
    assert run(x).strip() == str(n - best)


def test_exact_all_windows(run, x):
    p=list(map(int,x.split())); n,I=p[:2]; a=p[2:]; v=sorted(set(a)); b=8*I//n
    cap=len(v) if b>=len(v).bit_length() else 1<<b; best=0
    for i in range(len(v)):
        for j in range(i,len(v)):
            if j-i+1<=cap: best=max(best,sum(v[i]<=q<=v[j] for q in a))
    assert run(x).strip()==str(n-best)


def test_exact_prefix_frequency(run, x):
    p=list(map(int,x.split())); n,I=p[:2]; a=p[2:]; v=sorted(set(a)); b=8*I//n
    cap=len(v) if b>=len(v).bit_length() else 1<<b
    pref=[0]
    for q in v: pref.append(pref[-1]+a.count(q))
    best=max(pref[min(len(v),i+cap)]-pref[i] for i in range(len(v)))
    assert run(x).strip()==str(n-best)


def test_exact_endpoint_scan(run, x):
    p=list(map(int,x.split())); n,I=p[:2]; a=p[2:]; v=sorted(set(a)); b=8*I//n
    cap=len(v) if b>=len(v).bit_length() else 1<<b; ans=n
    for i,l in enumerate(v):
        for r in v[i:]:
            if len({l if q<l else r if q>r else q for q in a})<=cap:
                ans=min(ans,n-sum(l<=q<=r for q in a))
    assert run(x).strip()==str(ans)


def test_exact_sliding_counts(run, x):
    p=list(map(int,x.split())); n,I=p[:2]; a=p[2:]; v=sorted(set(a)); b=8*I//n
    cap=len(v) if b>=len(v).bit_length() else 1<<b; best=0
    for i in range(len(v)):
        kept=0
        for q in v[i:i+cap]:
            kept+=sum(z==q for z in a)
        best=max(best,kept)
    assert run(x).strip()==str(n-best)


def test_exact_budget_boundary(run, x):
    p=list(map(int,x.split())); n,I=p[:2]; a=p[2:]; v=sorted(set(a)); bits=(8*I)//n
    limit=len(v) if bits>=len(v).bit_length() else pow(2,bits); keep=0
    for i in range(len(v)):
        for j in range(i,min(len(v),i+limit)):
            keep=max(keep,sum(q in v[i:j+1] for q in a))
    assert run(x).strip()==str(n-keep)


def test_exact_sorted_interval(run, x):
    p=list(map(int,x.split())); n,I=p[:2]; a=p[2:]; s=sorted(a); v=sorted(set(a)); b=8*I//n
    cap=len(v) if b>=len(v).bit_length() else 1<<b; best=0
    for i in range(len(v)):
        for j in range(i,min(len(v),i+cap)):
            best=max(best,sum(v[i]<=q<=v[j] for q in s))
    assert run(x).strip()==str(n-best)

