def test_unique_position_oracle(run, x):
    out = run(x).strip()
    lines = x.split()
    n = int(lines[0])
    a = [int(v) for v in lines[1:]]
    if len(set(a)) == n:
        moves = sum(a) - n * (n - 1) // 2
        assert out == ('sjfnb' if moves % 2 else 'cslnb')
    else:
        assert out in ('sjfnb', 'cslnb')


def test_duplicate_position_oracle(run, x):
    out = run(x).strip()
    vals = [int(v) for v in x.split()[1:]]
    n = len(vals)
    b = sorted(vals)
    repeated = [b[i] for i in range(1, n) if b[i] == b[i - 1]]
    if repeated:
        if len(repeated) > 1 or repeated[0] == 0 or repeated[0] - 1 in b:
            expected = 'cslnb'
        else:
            moves = sum(b) - n * (n - 1) // 2
            expected = 'sjfnb' if moves % 2 else 'cslnb'
        assert out == expected
    else:
        assert out in ('sjfnb', 'cslnb')


