def test_small_game_bruteforce(run, x):
    from functools import lru_cache
    data = list(map(int, x.split()))
    n, a = data[0], data[1:]
    out = run(x).strip()
    if n > 8 or max(a, default=0) > 15:
        return
    @lru_cache(None)
    def wins(state):
        state = list(state)
        for i, v in enumerate(state):
            if v == 0:
                continue
            nxt = state[:]
            nxt[i] -= 1
            if len(set(nxt)) != len(nxt):
                continue
            if not wins(tuple(sorted(nxt))):
                return True
        return False
    expected = 'sjfnb' if wins(tuple(sorted(a))) else 'cslnb'
    assert out == expected


