def test_small_game_bruteforce_duplicate(run, x):
    from functools import lru_cache
    data = list(map(int, x.split()))
    n, a = data[0], data[1:]
    out = run(x).strip()
    if n > 7 or max(a, default=0) > 12:
        return
    @lru_cache(None)
    def losing(state):
        for i in range(len(state)):
            if state[i] == 0:
                continue
            candidate = list(state)
            candidate[i] -= 1
            if len(candidate) != len(set(candidate)):
                continue
            candidate.sort()
            if losing(tuple(candidate)):
                return False
        return True
    assert out == ('cslnb' if losing(tuple(sorted(a))) else 'sjfnb')

