def test_exhaustive_paths(run, x):
    out = run(x).strip()
    z = list(map(int, x.split()))
    n, k, q = z[:3]
    states = {(tuple(z[3:]), ())}
    for _ in range(q):
        nxt = set()
        for a, removed in states:
            for left in range(len(a) - k + 1):
                m = min(a[left:left + k])
                for p in range(left, left + k):
                    if a[p] == m:
                        nxt.add((a[:p] + a[p + 1:], removed + (m,)))
        states = nxt
    want = min(max(r) - min(r) for _, r in states)
    assert out == str(want)


def test_exhaustive_state_space(run, x):
    out = run(x).strip()
    v = list(map(int, x.split()))
    n, k, q = v[:3]
    frontier = {(tuple(v[3:]), tuple())}
    for step in range(q):
        following = set()
        for seq, chosen in frontier:
            for start in range(len(seq) - k + 1):
                low = min(seq[start:start + k])
                for index in range(start, start + k):
                    if seq[index] == low:
                        following.add((seq[:index] + seq[index + 1:], chosen + (low,)))
        frontier = following
    expected = min(max(chosen) - min(chosen) for seq, chosen in frontier)
    assert out == str(expected)


def test_exhaustive_tied_minima(run, x):
    out = run(x).strip()
    parts = list(map(int, x.split()))
    n, k, q = parts[:3]
    work = [(tuple(parts[3:]), ())]
    for _ in range(q):
        new_work = []
        for seq, history in work:
            for l in range(len(seq) - k + 1):
                minimum = min(seq[l:l + k])
                for pos in range(l, l + k):
                    if seq[pos] == minimum:
                        new_work.append((seq[:pos] + seq[pos + 1:], history + (minimum,)))
        work = list(set(new_work))
    expected = min(max(history) - min(history) for seq, history in work)
    assert out == str(expected)


def test_exhaustive_operation_definition(run, x):
    out = run(x).strip()
    data = list(map(int, x.split()))
    n, k, q = data[0], data[1], data[2]
    possibilities = {(tuple(data[3:]), tuple())}
    for _ in range(q):
        after = set()
        for current, removed in possibilities:
            for begin in range(0, len(current) - k + 1):
                segment = current[begin:begin + k]
                minimum = min(segment)
                for offset, value in enumerate(segment):
                    if value == minimum:
                        p = begin + offset
                        after.add((current[:p] + current[p + 1:], removed + (value,)))
        possibilities = after
    answer = min(max(removed) - min(removed) for current, removed in possibilities)
    assert out == str(answer)


def test_difference_of_input_values(run, x):
    out = run(x).strip()
    values = list(map(int, x.split()))[3:]
    assert out.isdigit()
