    states = {(a, 10**10, -1)}
    for _ in range(q):
        nxt = set()
        for cur, lo, hi in states:
            for i in range(len(cur) - k + 1):
                m = min(cur[i:i + k])
                for j in range(i, i + k):
                    if cur[j] == m:
                        nxt.add((cur[:j] + cur[j + 1:], min(lo, m), max(hi, m)))
