def test_exhaustive_recursive(run, x):
    p = list(map(int, x.split()))
    k, q, a = p[1], p[2], tuple(p[3:])
    best = [10**10]
    def visit(cur, removed):
        if len(removed) == q:
            best[0] = min(best[0], max(removed) - min(removed))
            return
        for i in range(len(cur) - k + 1):
            m = min(cur[i:i + k])
            for j in range(i, i + k):
                if cur[j] == m:
                    visit(cur[:j] + cur[j + 1:], removed + (m,))
    visit(a, ())
