        for cur, lo, hi in work:
            for left in range(len(cur) - k + 1):
                value = min(cur[left:left + k])
                for pos in range(left, left + k):
                    if cur[pos] == value:
                        new.append((cur[:pos] + cur[pos + 1:], value if lo is None else min(lo, value), value if hi is None else max(hi, value)))
