def test_recursive_prime_allocations(run, x):
    a = list(map(int, x.split()))
    n = a[0]
    m = 1
    for v in a[1:]:
        m *= v
    counts = []
    p = 2
    while p * p <= m:
        e = 0
        while m % p == 0:
            m //= p
            e += 1
        if e:
            counts.append(e)
        p += 1
    if m > 1:
        counts.append(1)
    want = 1
    for e in counts:
        total = [0]
        def distribute(slot, left):
            if slot == n - 1:
                total[0] += 1
                return
            for take in range(left + 1):
                distribute(slot + 1, left - take)
        distribute(0, e)
        want *= total[0]
    got = run(x).strip()
    assert got.isdecimal()
    assert int(got) == want % 1000000007


def test_composition_enumeration(run, x):
    z = list(map(int, x.split()))
    n = z[0]
    product = 1
    for q in z[1:]:
        product *= q
    es = []
    q = 2
    while q * q <= product:
        k = 0
        while product % q == 0:
            product //= q
            k += 1
        if k:
            es.append(k)
        q += 1
    if product != 1:
        es.append(1)
    answer = 1
    for e in es:
        def count(i, remaining):
            if i == n - 1:
                return 1
            return sum(count(i + 1, remaining - t) for t in range(remaining + 1))
        answer *= count(0, e)
    text = run(x).strip()
    assert text.isdecimal()
    assert int(text) == answer % 1000000007


