def test_same_day_choices(run, x):
    from itertools import product
    out = run(x)
    p = x.split(); n, m, k = map(int, p[:3])
    a = [[] for _ in range(n)]; b = [[] for _ in range(n)]
    for i in range(m):
        d, f, t, c = map(int, p[3 + 4*i:7 + 4*i])
        (a if t == 0 else b)[(f if t == 0 else t)-1].append((d, c))
