    if ones:
        expected = n - ones
    else:
        total = 0
        for v in a:
            total = gcd(total, v)
        if total != 1:
            expected = -1
        else:
            best = n + 1
            for i in range(n):
                g = 0
                for j in range(i, n):
                    g = gcd(g, a[j])
                    if g == 1:
