def test_layered_operation_enumeration(run, x):
    from math import gcd
    data = list(map(int, x.split()))
    n, start = data[0], tuple(data[1:])
    frontier = {start}
    expected = -1
    for steps in range(20):
        if any(all(v == 1 for v in state) for state in frontier):
            expected = steps
            break
        following = set()
        for state in frontier:
            for i in range(n - 1):
                g = gcd(state[i], state[i + 1])
                left = list(state)
                left[i] = g
                following.add(tuple(left))
