def test_second_exhaustive_oracle(run, x):
    from collections import deque
    from math import gcd
    data = list(map(int, x.split()))
    n, start = data[0], tuple(data[1:])
    got = int(run(x).strip())
    todo = deque([start])
    distance = {start: 0}
    while todo:
        s = todo.popleft()
        for i in range(n - 1):
            g = gcd(s[i], s[i + 1])
            for pos in (i, i + 1):
                t = list(s)
                t[pos] = g
                t = tuple(t)
                if t not in distance:
                    distance[t] = distance[s] + 1
                    todo.append(t)
    targets = [d for s, d in distance.items() if all(v == 1 for v in s)]
    assert got == (min(targets) if targets else -1)

