def test_exhaustive_matching(run, x):
    data = list(map(int, x.split()))
    n, k = data[0], data[1]
    terminals = [v - 1 for v in data[2:2 + 2 * k]]
    e = [[] for _ in range(n)]
    p = 2 + 2 * k
    for i in range(n - 1):
        a, b = data[p + 2 * i] - 1, data[p + 2 * i + 1] - 1
        e[a].append(b); e[b].append(a)
    d = [[0] * (2 * k) for _ in range(2 * k)]
    for i, s in enumerate(terminals):
        q, seen = [s], {s}
        for v in q:
            for w in e[v]:
                if w not in seen:
                    seen.add(w); d[i][terminals.index(w)] = d[i][terminals.index(v)] + 1 if w in terminals else 0
                    q.append(w)
        dist = [-1] * n; dist[s] = 0
        q = [s]
        for v in q:
            for w in e[v]:
                if dist[w] < 0:
                    dist[w] = dist[v] + 1; q.append(w)
        for j, t in enumerate(terminals): d[i][j] = dist[t]
    memo = {}
    def best(mask):
        if not mask: return 0
        if mask in memo: return memo[mask]
        i = (mask & -mask).bit_length() - 1
        rest = mask ^ (1 << i)
        ans = max(d[i][j] + best(rest ^ (1 << j)) for j in range(2 * k) if rest >> j & 1)
        memo[mask] = ans
        return ans
    out = run(x).strip()
    assert out.isdigit()
    assert int(out) == best((1 << (2 * k)) - 1)

