    for i in range(2 + m, len(a), 2):
        p, q = a[i] - 1, a[i + 1] - 1
        g[p].append(q); g[q].append(p)
    d = []
    for s in u:
        z = [-1] * n; z[s] = 0; q = deque([s])
        while q:
            v = q.popleft()
            for w in g[v]:
                if z[w] < 0:
                    z[w] = z[v] + 1; q.append(w)
        d.append([z[v] for v in u])
    @lru_cache(None)
    def best(mask):
        if not mask: return 0
        i = (mask & -mask).bit_length() - 1
        return max(d[i][j] + best(mask ^ (1 << i) ^ (1 << j)) for j in range(i + 1, m) if mask >> j & 1)
    out = run(x)
    assert int(out.strip()) == best((1 << m) - 1)

def test_recursive_pairings(run, x):
    from collections import deque
    from functools import lru_cache
    a = list(map(int, x.split()))
    n, k = a[0], a[1]
    u = [v - 1 for v in a[2:2 + 2 * k]]
    g = [[] for _ in range(n)]
    for i in range(2 + 2 * k, len(a), 2):
        v, w = a[i] - 1, a[i + 1] - 1
        g[v].append(w); g[w].append(v)
    dist = [[0] * n for _ in range(n)]
    for s in range(n):
        q = deque([s]); seen = [-1] * n; seen[s] = 0
        while q:
            v = q.popleft()
            for w in g[v]:
                if seen[w] == -1:
                    seen[w] = seen[v] + 1; q.append(w)
        dist[s] = seen
    @lru_cache(None)
    def f(rem):
        if not rem: return 0
        return max(dist[rem[0]][rem[i]] + f(rem[1:i] + rem[i + 1:]) for i in range(1, len(rem)))
    out = run(x)
    assert int(out.strip()) == f(tuple(u))

def test_edge_cut_oracle(run, x):
    a = list(map(int, x.split()))
    n, k = a[0], a[1]
    m = 2 * k
    marked = set(v - 1 for v in a[2:2 + m])
    g = [[] for _ in range(n)]
    for i in range(2 + m, len(a), 2):
        v, w = a[i] - 1, a[i + 1] - 1
        g[v].append(w); g[w].append(v)
    parent = [-1] * n; parent[0] = 0; order = [0]
    for v in order:
        for w in g[v]:
            if parent[w] == -1:
                parent[w] = v; order.append(w)
    cnt = [int(v in marked) for v in range(n)]
    ans = 0
    for v in reversed(order[1:]):
        ans += min(cnt[v], m - cnt[v])
        cnt[parent[v]] += cnt[v]
    out = run(x)
    assert int(out.strip()) == ans

def test_edge_cut_last_root(run, x):
    a = list(map(int, x.split()))
    n, k = a[0], a[1]
    m = 2 * k
    has = [0] * n
    for v in a[2:2 + m]: has[v - 1] = 1
    g = [[] for _ in range(n)]
    for i in range(2 + m, len(a), 2):
        v, w = a[i] - 1, a[i + 1] - 1
        g[v].append(w); g[w].append(v)
    root = n - 1; par = [-1] * n; par[root] = root; order = [root]
    for v in order:
        for w in g[v]:
            if par[w] < 0:
                par[w] = v; order.append(w)
    total = 0
    for v in reversed(order):
        if v != root:
            total += min(has[v], m - has[v])
            has[par[v]] += has[v]
    out = run(x)
    assert int(out.strip()) == total

