def test_literal_small_enumeration(run, x):
    try:
        lines = x.splitlines()
        n, m, k = map(int, lines[0].split())
        gov = [int(v) - 1 for v in lines[1].split()]
        existing = set()
        for line in lines[2:]:
            a, b = map(int, line.split()); a -= 1; b -= 1
            existing.add((min(a, b), max(a, b)))
        out = run(x).strip()
        assert out.isdigit()
        if n <= 6:
            missing = [(a, b) for a in range(n) for b in range(a + 1, n) if (a, b) not in existing]
            best = 0
            for mask in range(1 << len(missing)):
                parent = list(range(n))
                def find(a):
                    while parent[a] != a:
                        parent[a] = parent[parent[a]]; a = parent[a]
                    return a
                for a, b in existing:
                    ra, rb = find(a), find(b)
                    if ra != rb: parent[ra] = rb
                for i, (a, b) in enumerate(missing):
                    if mask >> i & 1:
                        ra, rb = find(a), find(b)
                        if ra != rb: parent[ra] = rb
                roots = [find(g) for g in gov]
                if len(set(roots)) == len(roots): best = max(best, mask.bit_count())
            assert int(out) == best
    except Exception:
        assert False

