    out = run(x).strip().split()
    assert len(out) == 1 and out[0].isdigit()
    value = int(out[0])
    assert 0 <= value <= n * (n - 1) // 2 - m


def test_component_completion_dsu(run, x):
    data = list(map(int, x.split()))
    n, m, k = data[:3]
    gov = data[3:3+k]
    edges = data[3+k:]
    parent = list(range(n))
    def find(a):
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a
    def join(a, b):
        a, b = find(a), find(b)
        if a != b: parent[b] = a
    for i in range(0, len(edges), 2): join(edges[i]-1, edges[i+1]-1)
    sizes = {}
    for v in range(n):
        r = find(v); sizes[r] = sizes.get(r, 0) + 1
    gr = {find(v-1) for v in gov}
    gs = [sizes[r] for r in gr]
    free = sum(s for r, s in sizes.items() if r not in gr)
    big = max(gs)
    expected = sum(s*(s-1)//2 for s in gs) - big*(big-1)//2 + (big+free)*(big+free-1)//2 - m
    assert int(run(x).strip()) == expected


def test_component_completion_bfs(run, x):
    lines = x.strip().splitlines()
    n, m, k = map(int, lines[0].split())
    governments = set(map(int, lines[1].split()))
    graph = [[] for _ in range(n+1)]
    for line in lines[2:]:
        a, b = map(int, line.split()); graph[a].append(b); graph[b].append(a)
    seen = set(); government_sizes = []; free = 0
    for start in range(1, n+1):
        if start in seen: continue
        stack = [start]; seen.add(start); comp = []
        while stack:
            v = stack.pop(); comp.append(v)
            for w in graph[v]:
                if w not in seen: seen.add(w); stack.append(w)
        if any(v in governments for v in comp): government_sizes.append(len(comp))
        else: free += len(comp)
    largest = max(government_sizes)
    total = sum(s*(s-1)//2 for s in government_sizes)
    total += (largest+free)*(largest+free-1)//2 - largest*(largest-1)//2
    assert int(run(x).strip()) == total - m


def test_exhaustive_small_component_assignment(run, x):
    import itertools
    data = list(map(int, x.split()))
    n, m, k = data[:3]
    if n > 10: return
    gov = set(data[3:3+k]); raw = data[3+k:]
    adj = [[] for _ in range(n+1)]
    for i in range(0, len(raw), 2):
        a, b = raw[i], raw[i+1]; adj[a].append(b); adj[b].append(a)
    seen = set(); fixed = []; loose = []
    for start in range(1, n+1):
        if start in seen: continue
        todo = [start]; seen.add(start); comp = []
        while todo:
            v = todo.pop(); comp.append(v)
            for w in adj[v]:
                if w not in seen: seen.add(w); todo.append(w)
        if any(v in gov for v in comp): fixed.append(len(comp))
        else: loose.append(len(comp))
    best = 0
    for choices in itertools.product(range(k), repeat=len(loose)):
        sizes = fixed[:]
        for size, target in zip(loose, choices): sizes[target] += size
        best = max(best, sum(s*(s-1)//2 for s in sizes))
    assert int(run(x).strip()) == best - m


def test_isolated_governments_completion(run, x):
    lines = x.strip().splitlines()
    n, m, k = map(int, lines[0].split())
    gov = set(map(int, lines[1].split()))
    incident = set()
    for line in lines[2:]:
        a, b = map(int, line.split()); incident.add(a); incident.add(b)
    if gov.isdisjoint(incident):
        expected = (n-k+1)*(n-k)//2 - m
        assert int(run(x).strip()) == expected
    else:
        assert int(run(x).strip()) >= 0


def test_zero_edge_case_formula(run, x):
    n, m, k = map(int, x.splitlines()[0].split())
    value = int(run(x).strip())
    if m == 0:
        assert value == (n-k+1)*(n-k)//2
    else:
        assert value >= 0


def test_each_government_component_accounted_for(run, x):
    data = list(map(int, x.split()))
    n, m, k = data[:3]; gov = data[3:3+k]; e = data[3+k:]
    adj = [[] for _ in range(n)]
    for i in range(0, len(e), 2):
        a, b = e[i]-1, e[i+1]-1; adj[a].append(b); adj[b].append(a)
    label = [-1]*n; sizes = []
    for v in range(n):
        if label[v] >= 0: continue
        q=[v]; label[v]=len(sizes); count=0
        for u in q:
            count += 1
            for w in adj[u]:
                if label[w] < 0: label[w]=label[v]; q.append(w)
        sizes.append(count)
    roots = {label[g-1] for g in gov}
    owned = [sizes[r] for r in roots]
    spare = n - sum(owned)
    largest = max(owned)
    expected = sum(t*(t-1)//2 for t in owned) + spare*largest + spare*(spare-1)//2 - m
    assert int(run(x).strip()) == expected


def test_answer_not_below_existing_completion_floor(run, x):
