def test_exhaustive_small_cube_count(run, x):
    data = [list(map(int, z.split())) for z in x.strip().splitlines()]
    n = data[0][0]
    tiles = data[1:]
    choices = {}
    oriented = []
    for i, row in enumerate(tiles):
        for r in range(4):
            q = tuple(row[r:] + row[:r])
            oriented.append((i, q))
            choices.setdefault(q, []).append((i, r))
    total = 0
    for ti, top in oriented:
        a, b, c, d = top
        for bi, bottom in oriented:
            if bi == ti:
                continue
            e, h, g, f = bottom
            need = [(a, e, f, b), (b, f, g, c), (c, g, h, d), (d, h, e, a)]
            def fill(k, used):
                if k == 4:
                    return 1
                ans = 0
                for qid, _ in choices.get(need[k], []):
                    if qid not in used:
                        ans += fill(k + 1, used | {qid})
                return ans
            total += fill(0, {ti, bi})
    out = run(x).strip()
    assert int(out) == total // 24


